#!/usr/bin/env bash
# Question 1: Images used by ${Q1_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/audit
mkdir -p /opt/course/audit
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q1_NS}-web" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-web" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-web' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl create namespace "${Q1_NS}-batch" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-batch" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-batch' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl create namespace "${Q1_NS}-edge" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-edge" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-edge' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF >/dev/null
apiVersion: apps/v1
kind: Deployment
metadata:
  name: storefront
  namespace: ${Q1_NS}-web
spec:
  replicas: 2
  selector:
    matchLabels: { app: storefront }
  template:
    metadata:
      labels: { app: storefront }
    spec:
      terminationGracePeriodSeconds: 1
      initContainers:
        - name: migrate
          image: alpine:3.20
          command: ["sh", "-c", "echo migrated"]
      containers:
        - name: web
          image: nginx:1.27-alpine
---
apiVersion: v1
kind: Pod
metadata:
  name: nightly
  namespace: ${Q1_NS}-batch
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: job
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata:
  name: sync-agent
  namespace: ${Q1_NS}-batch
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: agent
      image: alpine:3.21
      command: ["sleep", "infinity"]
    - name: shipper
      image: busybox:1.37
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata:
  name: gateway
  namespace: ${Q1_NS}-edge
spec:
  terminationGracePeriodSeconds: 1
  initContainers:
    - name: fetch-certs
      image: busybox:1.37
      command: ["sh", "-c", "echo fetched"]
  containers:
    - name: gateway
      image: httpd:2.4-alpine
EOF
kubectl -n "${Q1_NS}-web" rollout status deployment/storefront --timeout=180s >/dev/null
kubectl -n "${Q1_NS}-batch" wait --for=condition=Ready pod/nightly pod/sync-agent --timeout=180s >/dev/null
kubectl -n "${Q1_NS}-edge" wait --for=condition=Ready pod/gateway --timeout=180s >/dev/null
: "${Q1_NS}" "${Q1_NODE}"
